            if len(buf) < 5:
                return
            mtype, plen = struct.unpack_from("<BH", buf, 2)
            if PAYLOAD_SIZES.get(mtype) != plen:
                self.len_errors += 1
                del buf[:2]
                continue
            total = plen + FRAME_OVERHEAD
